changeSet.sql:

DROP TABLE if exists "Informacion Bancaria" ;

CREATE TABLE "Informacion Bancaria" (
    loan_id bigint PRIMARY KEY,
    entidad_financiera TEXT,
    tipo_de_cuenta TEXT,
    numero_de_cuenta TEXT,
    created_at TIMESTAMP,
    updated_at TIMESTAMP NULL
);


COMMENT ON COLUMN "Informacion Bancaria".loan_id IS 'Identificador Unico Prestamo';
COMMENT ON COLUMN "Informacion Bancaria".entidad_financiera IS 'Entidad Financiera';
COMMENT ON COLUMN "Informacion Bancaria".tipo_de_cuenta IS 'Tipo de Cuenta';
COMMENT ON COLUMN "Informacion Bancaria".numero_de_cuenta IS 'Número de Cuenta';
COMMENT ON COLUMN "Informacion Bancaria".created_at IS 'Creado en';
COMMENT ON COLUMN "Informacion Bancaria".updated_at IS 'Actualizado en';


